    m = 0
    for i in range(len(x) - 2):
        m += x[i] * x[i+1] * x[i+2]
    n = 0
    for i in range(len(x) - 3):
        n += x[i] * x[i+1] * x[i+2] * x[i+3]
    return m - n

def solve_m_minus_n(N):
    import itertools
    max_mn = -float('inf')
    for k in range(3, N + 1):
        # Try all partitions of N into k positive integers
        # To avoid too many partitions, let's use a simpler approach for small N
        def get_partitions(n, k):
            if k == 1:
                yield [n]
                return
            for i in range(1, n - k + 2):
                for p in get_partitions(n - i, k - 1):
                    yield [i] + p

        for x in get_partitions(N, k):
            max_mn = max(max_mn, calculate_m_minus_n(x))
    return max_mn

for N in range(3, 15):
    print(f"N={N}, max_m_minus_n={solve_m_minus_n(N)}")

