import itertools

def calculate_m(A):
    m = 0
    N = len(A)
    for i in range(N):
        for j in range(i + 1, N):
            for k in range(j + 1, N):
                if A[j] == A[i] + 1 and A[k] == A[j] + 1:
                    m += 1
    return m

def solve_max_m(N):
    max_m = 0
    # We only need to consider values from 1 to N
    # But that's too many. Let's restrict the values.
    # For N=5, the values will be small.
    for A in itertools.product(range(1, N + 1), repeat=N):
        max_m = max(max_m, calculate_m(A))
    return max_m

